    Evaluate a mathematical expression with support for parentheses,
    operators (*, /, +, -), negative numbers, and proper order of operations.

    Args:
        expr (str): The mathematical expression as a string.

    Returns:
        float: The result of evaluating the expression.

    Raises:
        ZeroDivisionError: If there's a division by zero.
        ValueError: For invalid characters or malformed expressions.
    """
    import operator

    # Tokenize
    tokens = []
    i = 0
    expr = expr.replace(' ', '').replace('\t', '')

    while i < len(expr):
        if not expr[i].isspace():
            if expr[i].isdigit() or (expr[i] == '.' and i + 1 < len(expr) and expr[i+1].isdigit()):
                j = i
                has_decimal = False
                if expr[j] == '.':
                    has_decimal = True
                    j += 1
                while j < len(expr):
                    ch = expr[j]
                    if ch.isdigit():
                        j += 1
                        continue
                    elif ch == '-' and (j + 1 < len(expr) and expr[j+1].isdigit()):
                        # Treat as unary minus
                        tokens.append('-')
                        i += 1
                        break
                    else:
                        break
                if has_decimal:
                    num_str = f"{expr[i:j]}".replace('.', '', 1) + '.' if not expr[i:j].endswith('.') else expr[i:j]
                    num = float(num_str)
                else:
                    num = float(expr[i:j])
                tokens.append(num)
                i = j
            elif expr[i] in '+-*/()':
                # Check for unary minus at start or after operator/parenthesis
                if expr[i] == '-' and (not tokens or tokens[-1] in ('-', ')')):
                    tokens.append('-')  # treat as unary
                else:
                    tokens.append(expr[i])
                i += 1
            else:
                raise ValueError(f"Invalid character '{expr[i]}'.")
        else:
            i += 1

    def safe_divide(a, b):
        if b == 0:
            raise ZeroDivisionError("division by zero")
        return a / b

    # Shunting-yard to RPN
    output_queue = []
    operator_stack = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    for token in tokens:
        if isinstance(token, float):
            output_queue.append(token)
        elif token in precedence:
            while (operator_stack and operator_stack[-1] in precedence and
                   precedence[operator_stack[-1]] >= precedence[token]):
                op = operator_stack.pop()
                if op == '-':
                    b = output_queue.pop()
